adcs_quat_t star_q, triad_q, selected_q, out_q, tmp;
int star_ok = 0, triad_ok = 0;
double star_res = 0.0, triad_res = 0.0;
double denom_s, denom_t, w_s, w_t, sum_w;
int invalid_cfg = 0;

/* 1. 配置校验（每次调用重算） */
if (rs_config.max_residual_rad < 0.0 || !isfinite(rs_config.max_residual_rad) ||
    rs_config.fuse_angle_rad < 0.0 || !isfinite(rs_config.fuse_angle_rad) ||
    rs_config.switch_margin_rad < 0.0 || !isfinite(rs_config.switch_margin_rad) ||
    rs_config.residual_weight_floor_rad <= 0.0 || !isfinite(rs_config.residual_weight_floor_rad) ||
    rs_config.output_alpha <= 0.0 || rs_config.output_alpha > 1.0 || !isfinite(rs_config.output_alpha) ||
    rs_config.fuse_angle_rad > ADCS_PI ||
    rs_config.switch_confirm_cycles < 1U || rs_config.switch_confirm_cycles > 20U ||
    rs_config.max_outage_cycles < 1U || rs_config.max_outage_cycles > 20U ||
    (rs_input.enable != 0 && rs_input.enable != 1)) {
    invalid_cfg = 1;
}

if (invalid_cfg) {
    rs_state.primary = RS_FAULT;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
    rs_state.outage = 0U;
    rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_output.source = RS_FAULT;
    rs_output.primary = RS_FAULT;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0U;
    rs_output.outage = 0U;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

/* 2. Disable：清源、证据、上一姿态 */
if (rs_input.enable == 0) {
    rs_state.primary = RS_NONE;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
    rs_state.outage = 0U;
    rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_output.source = RS_NONE;
    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0U;
    rs_output.outage = 0U;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

/* 3. 每个源可用性判定 */
if (rs_input.star_q_bi != NULL &&
    adcs_quat_normalize(rs_input.star_q_bi, &star_q) == ADCS_OK &&
    isfinite(rs_input.star_residual_rad) &&
    rs_input.star_residual_rad >= 0.0 &&
    rs_input.star_residual_rad <= rs_config.max_residual_rad) {
    star_ok = 1;
    star_res = rs_input.star_residual_rad;
}
if (rs_input.triad_q_bi != NULL &&
    adcs_quat_normalize(rs_input.triad_q_bi, &triad_q) == ADCS_OK &&
    isfinite(rs_input.triad_residual_rad) &&
    rs_input.triad_residual_rad >= 0.0 &&
    rs_input.triad_residual_rad <= rs_config.max_residual_rad) {
    triad_ok = 1;
    triad_res = rs_input.triad_residual_rad;
}

/* 4. 符号不变夹角 */
rs_output.disagreement_rad = 0.0;
if (star_ok && triad_ok) {
    double d = adcs_quat_abs_dot(&star_q, &triad_q);
    if (d > 1.0) d = 1.0;
    if (d < -1.0) d = -1.0;
    rs_output.disagreement_rad = 2.0 * acos(d);
}

/* 5. 主源迁移（FAULT 已 latch 则先恢复为非 FAULT 重新评估） */
if (rs_state.primary == RS_FAULT) {
    rs_state.primary = RS_NONE;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
}
if (rs_state.primary == RS_NONE) {
    if (star_ok) {
        rs_state.primary = RS_STAR;
    } else if (triad_ok) {
        rs_state.primary = RS_TRIAD;
    }
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
} else if (rs_state.primary == RS_STAR) {
    if (!star_ok) {
        if (triad_ok) {
            rs_state.primary = RS_TRIAD;
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        } else {
            rs_state.primary = RS_NONE;
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        }
    } else if (triad_ok) {
        if (triad_res + rs_config.switch_margin_rad <= star_res) {
            rs_state.candidate = RS_TRIAD;
            if (rs_state.candidate_good < rs_config.switch_confirm_cycles) {
                rs_state.candidate_good++;
            }
            if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
                rs_state.primary = RS_TRIAD;
                rs_state.candidate = RS_NONE;
                rs_state.candidate_good = 0U;
            }
        } else {
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        }
    } else {
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0U;
    }
} else if (rs_state.primary == RS_TRIAD) {
    if (!triad_ok) {
        if (star_ok) {
            rs_state.primary = RS_STAR;
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        } else {
            rs_state.primary = RS_NONE;
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        }
    } else if (star_ok) {
        if (star_res + rs_config.switch_margin_rad <= triad_res) {
            rs_state.candidate = RS_STAR;
            if (rs_state.candidate_good < rs_config.switch_confirm_cycles) {
                rs_state.candidate_good++;
            }
            if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
                rs_state.primary = RS_STAR;
                rs_state.candidate = RS_NONE;
                rs_state.candidate_good = 0U;
            }
        } else {
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        }
    } else {
        rs_state.candidate = RS_NONE;
        rs_state.candidate_good = 0U;
    }
}
rs_output.primary = rs_state.primary;
rs_output.candidate = rs_state.candidate;
rs_output.candidate_good = rs_state.candidate_good;

/* 6/7. 融合或发布主源 */
rs_output.star_weight = 0.0;
rs_output.triad_weight = 0.0;
if (star_ok && triad_ok && rs_output.disagreement_rad <= rs_config.fuse_angle_rad) {
    adcs_quat_t triad_aligned;
    double dot = star_q.w * triad_q.w + star_q.x * triad_q.x +
                 star_q.y * triad_q.y + star_q.z * triad_q.z;
    if (dot < 0.0) {
        triad_aligned = (adcs_quat_t){-triad_q.w, -triad_q.x, -triad_q.y, -triad_q.z};
    } else {
        triad_aligned = triad_q;
    }
    denom_s = rs_config.residual_weight_floor_rad + star_res;
    denom_t = rs_config.residual_weight_floor_rad + triad_res;
    w_s = 1.0 / denom_s;
    w_t = 1.0 / denom_t;
    sum_w = w_s + w_t;
    rs_output.star_weight = w_s / sum_w;
    rs_output.triad_weight = w_t / sum_w;
    tmp = (adcs_quat_t){
        rs_output.star_weight * star_q.w + rs_output.triad_weight * triad_aligned.w,
        rs_output.star_weight * star_q.x + rs_output.triad_weight * triad_aligned.x,
        rs_output.star_weight * star_q.y + rs_output.triad_weight * triad_aligned.y,
        rs_output.star_weight * star_q.z + rs_output.triad_weight * triad_aligned.z};
    if (adcs_quat_normalize(&tmp, &selected_q) != ADCS_OK) {
        selected_q = star_q;
    }
    rs_output.source = RS_FUSED;
} else if (rs_state.primary == RS_STAR && star_ok) {
    selected_q = star_q;
    rs_output.source = RS_STAR;
} else if (rs_state.primary == RS_TRIAD && triad_ok) {
    selected_q = triad_q;
    rs_output.source = RS_TRIAD;
} else {
    selected_q = (adcs_quat_t){1, 0, 0, 0};
    rs_output.source = RS_NONE;
}

/* 8. 符号对齐到上一发布 + α混合 + 归一化 */
tmp = selected_q;
{
    double dot = rs_state.previous_q_bi.w * selected_q.w +
                 rs_state.previous_q_bi.x * selected_q.x +
                 rs_state.previous_q_bi.y * selected_q.y +
                 rs_state.previous_q_bi.z * selected_q.z;
    if (dot < 0.0) {
        tmp = (adcs_quat_t){-selected_q.w, -selected_q.x, -selected_q.y, -selected_q.z};
    }
}
out_q = (adcs_quat_t){
    (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w + rs_config.output_alpha * tmp.w,
    (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.x + rs_config.output_alpha * tmp.x,
    (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y + rs_config.output_alpha * tmp.y,
    (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z + rs_config.output_alpha * tmp.z};
if (adcs_quat_normalize(&out_q, &rs_output.q_bi) != ADCS_OK) {
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
}
rs_state.previous_q_bi = rs_output.q_bi;

/* 9. 双源均不可用：NONE+单位，outage++，达上限 latch FAULT */
if (!star_ok && !triad_ok) {
    rs_output.source = RS_NONE;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    rs_state.previous_q_bi = rs_output.q_bi;
    rs_state.outage++;
    rs_output.outage = rs_state.outage;
    if (rs_state.outage >= rs_config.max_outage_cycles) {
        rs_state.primary = RS_FAULT;
        rs_output.primary = RS_FAULT;
        rs_output.source = RS_FAULT;
    }
} else {
    rs_state.outage = 0U;
    rs_output.outage = 0U;
}

