int star_usable = 0, triad_usable = 0;
int config_bad = 0;

if ((rs_config.enable != 0) && (rs_config.enable != 1)) config_bad = 1;
if (!isfinite(rs_config.max_residual_rad) || (rs_config.max_residual_rad < 0.0)) config_bad = 1;
if (!isfinite(rs_config.fuse_angle_rad) || (rs_config.fuse_angle_rad < 0.0) ||
    (rs_config.fuse_angle_rad > ADCS_PI)) config_bad = 1;
if (!isfinite(rs_config.switch_margin_rad) || (rs_config.switch_margin_rad < 0.0)) config_bad = 1;
if (!isfinite(rs_config.residual_weight_floor_rad) || (rs_config.residual_weight_floor_rad <= 0.0)) config_bad = 1;
if (!isfinite(rs_config.output_alpha) || (rs_config.output_alpha <= 0.0) || (rs_config.output_alpha > 1.0)) config_bad = 1;
if ((rs_config.switch_confirm_cycles < 1U) || (rs_config.switch_confirm_cycles > 20U)) config_bad = 1;
if ((rs_config.max_outage_cycles < 1U) || (rs_config.max_outage_cycles > 20U)) config_bad = 1;

if (config_bad) {
    rs_state.primary = RS_FAULT;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
    rs_state.outage = 0U;
    rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
