    rs_output.primary = RS_NONE;
    rs_output.candidate = RS_NONE;
    rs_output.candidate_good = 0U;
    rs_output.outage = 0U;
    rs_output.disagreement_rad = 0.0;
    rs_output.star_weight = 0.0;
    rs_output.triad_weight = 0.0;
    rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    return;
}

if (rs_input.star_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.star_q_bi, &star_q) == ADCS_OK) {
        if (isfinite(rs_input.star_residual_rad) &&
            (rs_input.star_residual_rad >= 0.0) &&
            (rs_input.star_residual_rad <= rs_config.max_residual_rad)) {
            star_usable = 1;
        }
    }
}
if (rs_input.triad_q_bi != NULL) {
    if (adcs_quat_normalize(rs_input.triad_q_bi, &triad_q) == ADCS_OK) {
        if (isfinite(rs_input.triad_residual_rad) &&
            (rs_input.triad_residual_rad >= 0.0) &&
            (rs_input.triad_residual_rad <= rs_config.max_residual_rad)) {
            triad_usable = 1;
        }
    }
}

if ((rs_state.primary != RS_STAR) && (rs_state.primary != RS_TRIAD)) {
    if (star_usable) rs_state.primary = RS_STAR;
    else if (triad_usable) rs_state.primary = RS_TRIAD;
    else rs_state.primary = RS_NONE;
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
}

if (rs_state.primary == RS_STAR && !star_usable) {
    if (triad_usable) { rs_state.primary = RS_TRIAD; rs_state.candidate = RS_NONE; rs_state.candidate_good = 0U; }
    else { rs_state.primary = RS_NONE; rs_state.candidate = RS_NONE; rs_state.candidate_good = 0U; }
