    if (star_usable) { rs_state.primary = RS_STAR; rs_state.candidate = RS_NONE; rs_state.candidate_good = 0U; }
    else { rs_state.primary = RS_NONE; rs_state.candidate = RS_NONE; rs_state.candidate_good = 0U; }
}

if (star_usable && triad_usable) {
    rs_source_t alt = RS_NONE;
    double primary_res = 0.0, alt_res = 0.0;
    if (rs_state.primary == RS_STAR) { alt = RS_TRIAD; primary_res = rs_input.star_residual_rad; alt_res = rs_input.triad_residual_rad; }
    else if (rs_state.primary == RS_TRIAD) { alt = RS_STAR; primary_res = rs_input.triad_residual_rad; alt_res = rs_input.star_residual_rad; }

    if (alt != RS_NONE) {
        if (alt_res + rs_config.switch_margin_rad <= primary_res) {
            if (rs_state.candidate == alt) {
                if (rs_state.candidate_good < rs_config.switch_confirm_cycles)
                    rs_state.candidate_good++;
            } else {
                rs_state.candidate = alt;
                rs_state.candidate_good = 1U;
            }
            if (rs_state.candidate_good >= rs_config.switch_confirm_cycles) {
                rs_state.primary = alt;
                rs_state.candidate = RS_NONE;
                rs_state.candidate_good = 0U;
            }
        } else {
            rs_state.candidate = RS_NONE;
            rs_state.candidate_good = 0U;
        }
    }
} else {
    rs_state.candidate = RS_NONE;
    rs_state.candidate_good = 0U;
}

rs_output.disagreement_rad = 0.0;
rs_output.star_weight = 0.0;
rs_output.triad_weight = 0.0;

if (star_usable && triad_usable) {
    double d = adcs_quat_abs_dot(&star_q, &triad_q);
    if (d > 1.0) d = 1.0;
    if (d < 0.0) d = 0.0;
    rs_output.disagreement_rad = 2.0 * acos(d);

    if (rs_output.disagreement_rad <= rs_config.fuse_angle_rad) {
        adcs_quat_t tq;
        double dot = star_q.w * triad_q.w + star_q.x * triad_q.x + star_q.y * triad_q.y + star_q.z * triad_q.z;
        if (dot < 0.0) {
            tq.w = -triad_q.w; tq.x = -triad_q.x; tq.y = -triad_q.y; tq.z = -triad_q.z;
        } else {
            tq = triad_q;
        }
        rs_output.star_weight = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.star_residual_rad);
        rs_output.triad_weight = 1.0 / (rs_config.residual_weight_floor_rad + rs_input.triad_residual_rad);

        adcs_quat_t fused;
        fused.w = rs_output.star_weight * star_q.w + rs_output.triad_weight * tq.w;
        fused.x = rs_output.star_weight * star_q.x + rs_output.triad_weight * tq.x;
        fused.y = rs_output.star_weight * star_q.y + rs_output.triad_weight * tq.y;
        fused.z = rs_output.star_weight * star_q.z + rs_output.triad_weight * tq.z;

        adcs_quat_t selected;
        (void)adcs_quat_normalize(&fused, &selected);

        adcs_quat_t aligned = selected;
        double pd = rs_state.previous_q_bi.w * selected.w + rs_state.previous_q_bi.x * selected.x +
                    rs_state.previous_q_bi.y * selected.y + rs_state.previous_q_bi.z * selected.z;
        if (pd < 0.0) {
            aligned.w = -selected.w; aligned.x = -selected.x; aligned.y = -selected.y; aligned.z = -selected.z;
        }
        adcs_quat_t blended;
        blended.w = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w + rs_config.output_alpha * aligned.w;
        blended.x = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.x + rs_config.output_alpha * aligned.x;
        blended.y = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y + rs_config.output_alpha * aligned.y;
        blended.z = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z + rs_config.output_alpha * aligned.z;
        (void)adcs_quat_normalize(&blended, &rs_output.q_bi);

        rs_state.previous_q_bi = rs_output.q_bi;
        rs_output.source = RS_FUSED;
        rs_output.primary = rs_state.primary;
        rs_output.candidate = rs_state.candidate;
        rs_output.candidate_good = rs_state.candidate_good;
        rs_output.outage = rs_state.outage;
        return;
    }
}

if (rs_state.primary == RS_STAR || rs_state.primary == RS_TRIAD) {
    adcs_quat_t pq = (rs_state.primary == RS_STAR) ? star_q : triad_q;
    adcs_quat_t aligned = pq;
    double pd = rs_state.previous_q_bi.w * pq.w + rs_state.previous_q_bi.x * pq.x +
                rs_state.previous_q_bi.y * pq.y + rs_state.previous_q_bi.z * pq.z;
    if (pd < 0.0) {
        aligned.w = -pq.w; aligned.x = -pq.x; aligned.y = -pq.y; aligned.z = -pq.z;
    }
    adcs_quat_t blended;
    blended.w = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w + rs_config.output_alpha * aligned.w;
    blended.x = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.x + rs_config.output_alpha * aligned.x;
    blended.y = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y + rs_config.output_alpha * aligned.y;
    blended.z = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z + rs_config.output_alpha * aligned.z;
    (void)adcs_quat_normalize(&blended, &rs_output.q_bi);
    rs_state.previous_q_bi = rs_output.q_bi;
    rs_output.source = rs_state.primary;
    rs_output.primary = rs_state.primary;
    rs_output.candidate = rs_state.candidate;
    rs_output.candidate_good = rs_state.candidate_good;
    rs_output.outage = rs_state.outage;
    return;
}

rs_state.outage++;
if (rs_state.outage >= rs_config.max_outage_cycles) {
    rs_state.primary = RS_FAULT;
}
rs_output.source = RS_NONE;
rs_output.primary = rs_state.primary;
rs_output.candidate = rs_state.candidate;
rs_output.candidate_good = rs_state.candidate_good;
rs_output.outage = rs_state.outage;
rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
rs_state.previous_q_bi = rs_output.q_bi;
return;

