    blended.w = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.w +
                rs_config.output_alpha * selected.w;
    blended.x = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.x +
                rs_config.output_alpha * selected.x;
    blended.y = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.y +
                rs_config.output_alpha * selected.y;
    blended.z = (1.0 - rs_config.output_alpha) * rs_state.previous_q_bi.z +
                rs_config.output_alpha * selected.z;
    (void)adcs_quat_normalize(&blended, &blended);

    rs_output.q_bi = blended;
    rs_state.previous_q_bi = blended;

    /* 9) 两者都不可用 */
    if ((!star_usable) && (!triad_usable)) {
        rs_output.source = RS_NONE;
        rs_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
        rs_state.previous_q_bi = (adcs_quat_t){1, 0, 0, 0};
        if (rs_state.outage < 0xFFFFFFFFU) rs_state.outage += 1U;
        if (rs_state.outage >= rs_config.max_outage_cycles) {
            rs_state.primary = RS_FAULT;
            rs_output.source = RS_FAULT;
        }
        rs_output.disagreement_rad = 0.0;
        rs_output.star_weight = 0.0;
        rs_output.triad_weight = 0.0;
    }

    /* 输出字段同步 */
    rs_output.primary = rs_state.primary;
    rs_output.candidate = rs_state.candidate;
    rs_output.candidate_good = rs_state.candidate_good;
    rs_output.outage = rs_state.outage;
}
